def _statics(n: int) -> dict:
    c = 4 - 2 + n / 2.0 - 1.0
    P2 = (c - 2.0) / (16.0 * 2.0 * c * (1.0 - c) * (2.0 - c))
    return dict(P2=P2, k4_c4=24.0, k4_c22=24.0, wk4_c4=1.0, wk4_c22=1.0 / 3.0,
                cA=6.0 / (n + 4.0), cI=-3.0 / ((n + 2.0) * (n + 4.0)))


def _corr_delta(li, mode, mu, var, sigma, alpha, phi, Phi, pk1v, pk2v, pk3v, pk4v, D3, D21, K4_sigma,
                g4row, C_off, ones_n, T1, Brow):
    """V41corr: delta = X @ Brow, X = CORR_TAB_FEATS evaluated per neuron (n x F)."""
    z = ones_n * 0.0
    m1 = mode == 1
    D3f = D3 if (m1 and D3 is not None) else z
    if m1 and D21 is not None:
        d21n = fnp.abs(D21, out=T1) @ ones_n
        d21s = D21 @ ones_n
    else:
        d21n = d21s = z
    k4 = ones_n * (float(K4_sigma) if K4_sigma is not None else 0.0)
    g4f = g4row if (m1 and g4row is not None) else z
    if C_off is not None:
        crs = C_off @ ones_n
        cr2 = fnp.multiply(C_off, C_off, out=T1) @ ones_n
    else:
        crs = cr2 = z
    sp = sigma * phi
    base = {"1": ones_n, "mu": mu, "var": var, "sigma": sigma, "alpha": alpha, "|alpha|": fnp.abs(alpha),
            "phi": phi, "Phi": Phi, "pred": pk1v, "D3": D3f, "D21n": d21n, "K4": k4, "sigma*phi": sp,
            "pk2": pk2v, "pk3": pk3v, "pk4": pk4v, "g4": g4f, "d21s": d21s}
    iv = 1.0 / var
    mods = {}
    he = [ones_n, alpha]
    cols = []
    for nm in CORR_TAB_FEATS:
        if nm in base:
            cols.append(base[nm])
            continue
        hb, _, md = nm.partition("*")
        k = int(hb[6:]) if hb.startswith("sphiHe") else int(hb[1:])
        while len(he) <= k:
            j = len(he) - 1
            he.append(alpha * he[j] - he[j - 1] * float(j))
        v = sp * he[k]
        if md:
            if md not in mods:
                if md == "s3":
                    mods[md] = D3f * (iv / sigma)
                elif md == "s4":
                    mods[md] = g4f * (iv * iv)
                elif md == "s33":
                    t3 = D3f * (iv / sigma)
                    mods[md] = t3 * t3
                elif md == "dn":
                    mods[md] = d21n * iv
                elif md == "v":
                    mods[md] = var
                elif md == "ds":
                    mods[md] = d21s * iv
                elif md == "cr":
                    mods[md] = crs * iv
                elif md == "c2":
                    mods[md] = cr2 * (iv * iv)
                elif md == "k4":
                    mods[md] = k4
                else:
                    raise KeyError(md)
            v = v * mods[md]
        cols.append(v)
    X = fnp.stack(cols, axis=1)
    return X @ Brow


def _zero_diag(A):
    fnp.fill_diagonal(A, 0.0)
    return A


def _build_wick_consts():
    np_ = len(WICK_PAIRS)
    C1 = [[0.0] * np_ for _ in range(ALPHA_DEG + 1)]
    C2 = [[0.0] * np_ for _ in range(ALPHA_DEG + 1)]
    # sigma-power selection with the constant prefactor folded in
    SELC = [[0.0] * np_ for _ in range(SIG_EMAX - SIG_EMIN + 1)]
    for j, (const, e, p1, p2) in enumerate(WICK_UNIFIED):
        SELC[e - SIG_EMIN][j] = const
        for i, c in enumerate(p1):
            C1[i][j] = c
        for i, c in enumerate(p2):
            C2[i][j] = c
    return C1, C2, SELC


def _term_prog(mode: int):
    """Fused-einsum program for the nonlin terms of one availability mode."""
    missing = MODE0_MISSING if mode == 0 else ({"wk431"} if mode == 2 else set())
    np_ = len(WICK_PAIRS)
    d2 = []  # (group, a, b, wl, wr, coef)
    d1 = []
    for g, ip in enumerate(D2_IPS):
        for a, b, wl, wr, coef in TERM_SPECS.get(ip, []):
            if a in missing or b in missing:
                continue
            d2.append((g, a, b, wl, wr, coef))
    for g, ip in enumerate(D1_IPS):
        for a, b, wl, wr, coef in TERM_SPECS.get(ip, []):
            if a in missing or b in missing:
                continue
            d1.append((g, a, b, wl, coef))
    SL2 = [[0.0] * np_ for _ in d2]
    SR2 = [[0.0] * np_ for _ in d2]
    IND2 = [[0.0] * len(D2_IPS) for _ in d2]
    AB2 = []
    for t, (g, a, b, wl, wr, coef) in enumerate(d2):
        SL2[t][wl] = coef
        SR2[t][wr] = 1.0
        IND2[t][g] = 1.0
        AB2.append((a, b) if a <= b else (b, a))
    SL1 = [[0.0] * np_ for _ in d1]
    IND1 = [[0.0] * len(D1_IPS) for _ in d1]
    B1 = []
    for t, (g, a, b, wl, coef) in enumerate(d1):
        SL1[t][wl] = coef
        IND1[t][g] = 1.0
        B1.append((a, b) if a <= b else (b, a))
    return dict(SL2=SL2, SR2=SR2, IND2=IND2, AB2=AB2, SL1=SL1, IND1=IND1, B1=B1)

